import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface AnalysisSection {
  title: string;
  items: string[];
}

export interface ChecklistItem {
  id: string;
  label: string;
  status: 'success' | 'warning' | 'error' | 'pending';
  comment: string;
}

export interface AssemblyQuestion {
  question: string;
  suggestedResponse: string;
  legalBasis: string;
}

export interface AuditReport {
  strengths: string[];
  improvements: string[];
  corrections: string[];
  criticalities: string[];
  checklist: ChecklistItem[];
  assemblySimulator: AssemblyQuestion[];
  accountingMethodDetected: 'Competenza' | 'Cassa' | 'Misto' | 'Non Rilevato';
  structuralVerification: {
    register: boolean;
    summary: boolean;
    note: boolean;
  };
}

export enum AppState {
  IDLE = 'idle',
  UPLOADING = 'uploading',
  ANALYZING = 'analyzing',
  REPORT_READY = 'report_ready',
  ERROR = 'error'
}

import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_PROMPT = `
Sei un esperto revisore condominiale senior specializzato in legislazione italiana (Art. 1130 bis C.C.) e standard qualitativi ANACI.
Analizza il documento fornito (rendiconto condominiale) e produci un "Rapporto di Revisione" dettagliato.

Dovrai restituire un JSON strutturato con queste sezioni:
1. "strengths": Punti di forza (Compliance positiva).
2. "improvements": Suggerimenti di miglioramento basati sulla Guida ANACI.
3. "corrections": Errori tecnici o mancate quadrature.
4. "criticalities": Rischi di impugnazione (violazioni gravi).
5. "checklist": Valutazione semaforica di 5 punti chiave (Registro, Situazione Patrimoniale, Fondi, Rapporti in corso, Passaggio consegne).
6. "assemblySimulator": Simulatore di assemblea con domande probabili dei condomini e risposte suggerite.
7. "accountingMethodDetected": Rileva se è Competenza, Cassa o Misto.
8. "structuralVerification": Verifica presenza di Registro, Riepilogo, Nota.

Istruzioni di stile: professionale, tecnico ma intellegibile, citando capitoli della guida ANACI o articoli del Codice Civile dove pertinente.
`;

export async function analyzeFinancialDocument(fileBase64: string, mimeType: string): Promise<AuditReport> {
  const model = "gemini-3-pro-preview";

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { text: ANALYSIS_PROMPT },
        { inlineData: { data: fileBase64, mimeType } }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          corrections: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalities: { type: Type.ARRAY, items: { type: Type.STRING } },
          checklist: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                label: { type: Type.STRING },
                status: { type: Type.STRING, description: "success, warning, error, pending" },
                comment: { type: Type.STRING }
              }
            }
          },
          assemblySimulator: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                suggestedResponse: { type: Type.STRING },
                legalBasis: { type: Type.STRING }
              }
            }
          },
          accountingMethodDetected: { type: Type.STRING },
          structuralVerification: {
            type: Type.OBJECT,
            properties: {
              register: { type: Type.BOOLEAN },
              summary: { type: Type.BOOLEAN },
              note: { type: Type.BOOLEAN }
            }
          }
        },
        required: ["strengths", "improvements", "corrections", "criticalities", "checklist", "assemblySimulator", "accountingMethodDetected", "structuralVerification"]
      }
    }
  });

  const text = response.text || "{}";
  return JSON.parse(text) as AuditReport;
}

import React, { useRef, useState } from 'react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  isLoading: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, isLoading }) => {
  const [dragActive, setDragActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileSelect(e.target.files[0]);
    }
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div 
        className={`relative border-2 border-dashed rounded-2xl p-12 transition-all flex flex-col items-center justify-center text-center
          ${dragActive ? 'border-emerald-500 bg-emerald-50' : 'border-slate-300 bg-white'}
          ${isLoading ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer hover:border-emerald-400 hover:bg-slate-50'}
        `}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => !isLoading && inputRef.current?.click()}
      >
        <input 
          ref={inputRef}
          type="file" 
          accept=".pdf" 
          className="hidden" 
          onChange={handleChange}
          disabled={isLoading}
        />

        <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mb-6">
          <i className={`fas fa-cloud-upload-alt text-3xl ${dragActive ? 'text-emerald-500' : 'text-slate-400'}`}></i>
        </div>

        <h3 className="text-xl font-bold text-slate-800 mb-2">Carica il Rendiconto</h3>
        <p className="text-slate-500 text-sm max-w-sm">
          Seleziona il fascicolo PDF completo (Registro, Riepilogo, Nota, Riparto) per avviare l'audit digitale.
        </p>

        <div className="mt-8">
          <button 
            className="px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl shadow-md transition-colors disabled:opacity-50"
            disabled={isLoading}
          >
            Sfoglia Documenti
          </button>
        </div>
      </div>

      <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          { icon: 'fa-check-circle', text: 'Analisi Art. 1130 bis C.C.' },
          { icon: 'fa-shield-alt', text: 'Standard ANACI' },
          { icon: 'fa-file-invoice', text: 'Quadrature Automatiche' }
        ].map((item, idx) => (
          <div key={idx} className="flex items-center space-x-3 bg-white p-4 rounded-xl border border-slate-200">
            <i className={`fas ${item.icon} text-emerald-500`}></i>
            <span className="text-xs font-semibold text-slate-700">{item.text}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

