const Section: React.FC<{ cardTitle: string, icon: string, items: string[], type: 'positive' | 'neutral' | 'warning' | 'danger' }> = ({ cardTitle, icon, items, type }) => {
  const getColors = () => {
    switch(type) {
      case 'positive': return 'border-emerald-100 bg-emerald-50/30';
      case 'warning': return 'border-amber-100 bg-amber-50/30';
      case 'danger': return 'border-rose-100 bg-rose-50/30';
      default: return 'border-slate-100 bg-slate-50/30';
    }
  };

  return (
    <div className={`bg-white rounded-2xl shadow-sm border ${getColors()} p-6`}>
      <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
        <i className={`fas ${icon} mr-2`}></i> {cardTitle}
      </h3>
      <ul className="space-y-3">
        {items.length > 0 ? items.map((item, i) => (
          <li key={i} className="flex items-start space-x-3 text-sm text-slate-700">
            <span className="mt-1 w-1.5 h-1.5 rounded-full bg-slate-300 flex-shrink-0"></span>
            <span>{item}</span>
          </li>
        )) : (
          <li className="text-slate-400 text-xs italic">Nessun rilievo identificato in questa sezione.</li>
        )}
      </ul>
    </div>
  );
};

import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { FileUpload } from './components/FileUpload';
import { AuditDashboard } from './components/AuditDashboard';
import { analyzeFinancialDocument } from './services/geminiService';
import { AuditReport, AppState } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [report, setReport] = useState<AuditReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleFileSelect = async (file: File) => {
    setState(AppState.ANALYZING);
    setError(null);

    try {
      const base64 = await fileToBase64(file);
      const mimeType = file.type;
      const result = await analyzeFinancialDocument(base64, mimeType);

      setReport(result);
      setState(AppState.REPORT_READY);
    } catch (err: any) {
      console.error("Analysis failed:", err);
      setError("Si è verificato un errore durante l'analisi del documento. Assicurati che il PDF sia leggibile e riprova.");
      setState(AppState.ERROR);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = reader.result as string;
        resolve(base64String.split(',')[1]);
      };
      reader.onerror = error => reject(error);
    });
  };

  return (
    <Layout>
      {state === AppState.IDLE && (
        <div className="text-center py-12">
          <div className="max-w-3xl mx-auto px-4">
            <span className="inline-block px-3 py-1 rounded-full bg-emerald-100 text-emerald-700 text-[10px] font-bold uppercase tracking-wider mb-6">Versione Professionale</span>
            <h2 className="text-4xl font-extrabold text-slate-900 mb-4">Certifica il tuo Rendiconto</h2>
            <p className="text-slate-500 text-lg mb-12">
              L'IA al servizio degli amministratori ANACI. Analizza la trasparenza, la contabilità e la conformità legale dei tuoi rendiconti in pochi secondi.
            </p>
            <FileUpload onFileSelect={handleFileSelect} isLoading={false} />
          </div>
        </div>
      )}

      {state === AppState.ANALYZING && (
        <div className="flex flex-col items-center justify-center py-24 space-y-6">
          <div className="relative">
            <div className="w-24 h-24 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <i className="fas fa-brain text-emerald-600 text-2xl animate-pulse"></i>
            </div>
          </div>
          <div className="text-center">
            <h3 className="text-xl font-bold text-slate-800">Elaborazione in corso...</h3>
            <p className="text-slate-500 text-sm mt-2">L'IA sta eseguendo l'OCR e analizzando la struttura secondo l'Art. 1130 bis C.C.</p>
            <div className="mt-8 space-y-2">
              <div className="flex items-center space-x-2 text-xs text-slate-400">
                <i className="fas fa-check text-emerald-500"></i>
                <span>Estrazione testi e tabelle</span>
              </div>
              <div className="flex items-center space-x-2 text-xs text-slate-400">
                <i className="fas fa-sync animate-spin text-emerald-500"></i>
                <span>Verifica "Trinità Documentale"</span>
              </div>
              <div className="flex items-center space-x-2 text-xs text-slate-400">
                <span>Incrocio quadrature finanziarie</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {state === AppState.REPORT_READY && report && (
        <AuditDashboard report={report} onReset={() => setState(AppState.IDLE)} />
      )}

      {state === AppState.ERROR && (
        <div className="max-w-md mx-auto py-12 text-center bg-white rounded-2xl border border-rose-100 p-8 shadow-sm">
          <div className="w-16 h-16 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
            <i className="fas fa-exclamation-circle text-3xl"></i>
          </div>
          <h3 className="text-lg font-bold text-slate-800 mb-2">Errore di Analisi</h3>
          <p className="text-slate-500 text-sm mb-8">{error}</p>
          <button 
            onClick={() => setState(AppState.IDLE)}
            className="w-full py-3 bg-slate-900 text-white font-bold rounded-xl hover:bg-slate-800 transition"
          >
            Riprova
          </button>
        </div>
      )}
    </Layout>
  );
};

export default App;

