import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport, FileData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_PROMPT = `
Sei un esperto revisore condominiale senior specializzato in legislazione italiana (Art. 1130 bis C.C.) e standard qualitativi ANACI.
Analizza i documenti forniti (che compongono il rendiconto condominiale) e produci un "Rapporto di Revisione" dettagliato.
Il rendiconto può essere suddiviso in più file (Registro, Riepilogo, Nota, Riparto). Considerali come un unico corpus documentale.

Dovrai restituire un JSON strutturato con queste sezioni:
1. "strengths": Punti di forza (Compliance positiva).
2. "improvements": Suggerimenti di miglioramento basati sulla Guida ANACI.
3. "corrections": Errori tecnici o mancate quadrature.
4. "criticalities": Rischi di impugnazione (violazioni gravi).
5. "checklist": Valutazione semaforica di 5 punti chiave (Registro, Situazione Patrimoniale, Fondi, Rapporti in corso, Passaggio consegne).
6. "assemblySimulator": Simulatore di assemblea con domande probabili dei condomini e risposte suggerite.
7. "accountingMethodDetected": Rileva se è Competenza, Cassa o Misto.
8. "structuralVerification": Verifica presenza di Registro, Riepilogo, Nota.

Istruzioni di stile: professionale, tecnico ma intellegibile, citando capitoli della guida ANACI o articoli del Codice Civile dove pertinente. Rispondi in Italiano.
`;

export async function analyzeFinancialDocuments(files: FileData[]): Promise<AuditReport> {
  const model = "gemini-3-pro-preview";

  const parts = [
    { text: ANALYSIS_PROMPT },
    ...files.map(f => ({
      inlineData: { data: f.base64, mimeType: f.mimeType }
    }))
  ];

  const response = await ai.models.generateContent({
    model,
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          corrections: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalities: { type: Type.ARRAY, items: { type: Type.STRING } },
          checklist: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                label: { type: Type.STRING },
                status: { type: Type.STRING, description: "success, warning, error, pending" },
                comment: { type: Type.STRING }
              }
            }
          },
          assemblySimulator: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                suggestedResponse: { type: Type.STRING },
                legalBasis: { type: Type.STRING }
              }
            }
          },
          accountingMethodDetected: { type: Type.STRING },
          structuralVerification: {
            type: Type.OBJECT,
            properties: {
              register: { type: Type.BOOLEAN },
              summary: { type: Type.BOOLEAN },
              note: { type: Type.BOOLEAN }
            }
          }
        },
        required: ["strengths", "improvements", "corrections", "criticalities", "checklist", "assemblySimulator", "accountingMethodDetected", "structuralVerification"]
      }
    }
  });

  const text = response.text || "{}";
  return JSON.parse(text) as AuditReport;
}

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { FileUpload } from './components/FileUpload';
import { AuditDashboard } from './components/AuditDashboard';
import { analyzeFinancialDocuments } from './services/geminiService';
import { AuditReport, AppState, Folder, StatementEntry, AppView, FileData } from './types';

const STORAGE_KEY = 'condoaudit_data';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [folders, setFolders] = useState<Folder[]>([]);
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeEntryId, setActiveEntryId] = useState<string | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [error, setError] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setFolders(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    } else {
      // Initial empty state
      setFolders([{ id: 'default', name: 'Condominio Esempio', entries: [] }]);
    }
  }, []);

  useEffect(() => {
    if (folders.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(folders));
    }
  }, [folders]);

  const activeFolder = folders.find(f => f.id === activeFolderId);
  const activeEntry = activeFolder?.entries.find(e => e.id === activeEntryId);

  const createFolder = () => {
    const name = prompt("Nome del nuovo condominio/cartella:");
    if (name) {
      const newFolder: Folder = { id: Date.now().toString(), name, entries: [] };
      setFolders([...folders, newFolder]);
    }
  };

  const createEntry = (folderId: string) => {
    const title = prompt("Titolo del rendiconto (es. Ordinario 2023):");
    if (title) {
      const newEntry: StatementEntry = {
        id: Date.now().toString(),
        title,
        files: [],
        status: 'draft',
        createdAt: Date.now()
      };
      setFolders(folders.map(f => f.id === folderId ? { ...f, entries: [newEntry, ...f.entries] } : f));
    }
  };

  const deleteFolder = (id: string) => {
    if (confirm("Eliminare definitivamente questa cartella e tutti i rendiconti contenuti?")) {
      setFolders(folders.filter(f => f.id !== id));
      if (activeFolderId === id) {
        setView(AppView.DASHBOARD);
        setActiveFolderId(null);
      }
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = reader.result as string;
        resolve(base64String.split(',')[1]);
      };
      reader.onerror = error => reject(error);
    });
  };

  const addFilesToEntry = async (folderId: string, entryId: string, files: FileList) => {
    const newFiles: FileData[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (file.type !== 'application/pdf') continue;
      const base64 = await fileToBase64(file);
      newFiles.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        base64,
        mimeType: file.type
      });
    }

    setFolders(folders.map(f => {
      if (f.id === folderId) {
        return {
          ...f,
          entries: f.entries.map(e => e.id === entryId ? { ...e, files: [...e.files, ...newFiles] } : e)
        };
      }
      return f;
    }));
  };

  const removeFileFromEntry = (folderId: string, entryId: string, fileId: string) => {
    setFolders(folders.map(f => {
      if (f.id === folderId) {
        return {
          ...f,
          entries: f.entries.map(e => e.id === entryId ? { ...e, files: e.files.filter(file => file.id !== fileId) } : e)
        };
      }
      return f;
    }));
  };

  const runAnalysis = async (folderId: string, entryId: string) => {
    const folder = folders.find(f => f.id === folderId);
    const entry = folder?.entries.find(e => e.id === entryId);
    if (!entry || entry.files.length === 0) return;

    setAppState(AppState.ANALYZING);
    setError(null);

    try {
      const report = await analyzeFinancialDocuments(entry.files);
      setFolders(folders.map(f => {
        if (f.id === folderId) {
          return {
            ...f,
            entries: f.entries.map(e => e.id === entryId ? { ...e, status: 'completed', report } : e)
          };
        }
        return f;
      }));
      setActiveEntryId(entryId);
      setView(AppView.REPORT_VIEW);
      setAppState(AppState.IDLE);
    } catch (err) {
      console.error(err);
      setError("Errore durante l'analisi. Riprova più tardi.");
      setAppState(AppState.IDLE);
    }
  };

  return (
    <Layout>
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar - Folders Navigation */}
        <aside className="w-full lg:w-64 flex-shrink-0 space-y-4">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400">Condomini</h3>
              <button onClick={createFolder} className="p-1 hover:text-emerald-600 transition">
                <i className="fas fa-plus-circle"></i>
              </button>
            </div>
            <nav className="space-y-1">
              {folders.map(folder => (
                <div key={folder.id} className="group flex items-center">
                  <button
                    onClick={() => {
                      setActiveFolderId(folder.id);
                      setView(AppView.FOLDER_DETAIL);
                    }}
                    className={`flex-grow text-left px-3 py-2 rounded-lg text-sm transition-all flex items-center space-x-2 ${activeFolderId === folder.id ? 'bg-emerald-50 text-emerald-700 font-semibold' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    <i className={`fas fa-folder${activeFolderId === folder.id ? '-open' : ''} ${activeFolderId === folder.id ? 'text-emerald-500' : 'text-slate-400'}`}></i>
                    <span className="truncate">{folder.name}</span>
                  </button>
                  <button onClick={() => deleteFolder(folder.id)} className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-rose-500 transition">
                    <i className="fas fa-trash-alt text-xs"></i>
                  </button>
                </div>
              ))}
              {folders.length === 0 && <p className="text-[11px] text-slate-400 italic p-3">Nessun condominio creato.</p>}
            </nav>
          </div>
        </aside>

        {/* Main Content Area */}
        <section className="flex-grow">
          {appState === AppState.ANALYZING ? (
            <div className="flex flex-col items-center justify-center py-24 space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <i className="fas fa-brain text-emerald-600 text-2xl animate-pulse"></i>
                </div>
              </div>
              <div className="text-center">
                <h3 className="text-xl font-bold text-slate-800">Analisi in corso...</h3>
                <p className="text-slate-500 text-sm mt-2">L'IA sta elaborando i file caricati per il rendiconto.</p>
              </div>
            </div>
          ) : (
            <>
              {view === AppView.DASHBOARD && (
                <div className="bg-white rounded-2xl p-12 text-center border border-slate-200 shadow-sm">
                  <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6">
                    <i className="fas fa-building text-3xl"></i>
                  </div>
                  <h2 className="text-2xl font-bold text-slate-800 mb-2">Benvenuto in CondoAudit AI</h2>
                  <p className="text-slate-500 max-w-md mx-auto mb-8">
                    Seleziona un condominio dalla barra laterale per gestire i rendiconti o creane uno nuovo per iniziare.
                  </p>
                  <button onClick={createFolder} className="px-6 py-3 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 transition">
                    Nuovo Condominio
                  </button>
                </div>
              )}

              {view === AppView.FOLDER_DETAIL && activeFolder && (
                <div className="space-y-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-2xl font-bold text-slate-900">{activeFolder.name}</h2>
                      <p className="text-slate-500 text-sm">Gestione rendiconti e audit</p>
                    </div>
                    <button
                      onClick={() => createEntry(activeFolder.id)}
                      className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm font-bold hover:bg-slate-800 transition flex items-center"
                    >
                      <i className="fas fa-plus mr-2"></i> Nuovo Rendiconto
                    </button>
                  </div>

                  <div className="grid grid-cols-1 gap-6">
                    {activeFolder.entries.map(entry => (
                      <div key={entry.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition hover:shadow-md">
                        <div className="p-6">
                          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div className="flex items-start space-x-4">
                              <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${entry.status === 'completed' ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>
                                <i className={`fas ${entry.status === 'completed' ? 'fa-file-circle-check' : 'fa-file-invoice'} text-xl`}></i>
                              </div>
                              <div>
                                <h3 className="text-lg font-bold text-slate-800">{entry.title}</h3>
                                <p className="text-xs text-slate-400">Creato il {new Date(entry.createdAt).toLocaleDateString('it-IT')}</p>
                                <div className="mt-2 flex space-x-2">
                                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${entry.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                                    {entry.status === 'completed' ? 'Analizzato' : 'Bozza'}
                                  </span>
                                  <span className="text-[10px] font-medium text-slate-400 flex items-center">
                                    <i className="fas fa-paperclip mr-1"></i> {entry.files.length} file
                                  </span>
                                </div>
                              </div>
                            </div>

                            <div className="flex items-center space-x-2">
                              {entry.status === 'completed' && (
                                <button
                                  onClick={() => {
                                    setActiveEntryId(entry.id);
                                    setView(AppView.REPORT_VIEW);
                                  }}
                                  className="px-4 py-2 bg-emerald-50 text-emerald-700 rounded-lg text-sm font-bold hover:bg-emerald-100 transition"
                                >
                                  Visualizza Report
                                </button>
                              )}
                              <button
                                onClick={() => runAnalysis(activeFolder.id, entry.id)}
                                disabled={entry.files.length === 0}
                                className={`px-4 py-2 rounded-lg text-sm font-bold transition flex items-center ${entry.files.length > 0 ? 'bg-slate-900 text-white hover:bg-slate-800' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}
                              >
                                {entry.status === 'completed' ? 'Riesegui Audit' : 'Avvia Audit'}
                              </button>
                            </div>
                          </div>

                          {/* Files Section */}
                          <div className="mt-6 pt-6 border-t border-slate-100">
                            <h4 className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3">Documenti caricati</h4>
                            <div className="flex flex-wrap gap-2 mb-4">
                              {entry.files.map(file => (
                                <div key={file.id} className="group relative bg-slate-50 border border-slate-200 px-3 py-1.5 rounded-lg flex items-center space-x-2">
                                  <i className="fas fa-file-pdf text-rose-500 text-xs"></i>
                                  <span className="text-xs text-slate-600 max-w-[150px] truncate">{file.name}</span>
                                  <button
                                    onClick={() => removeFileFromEntry(activeFolder.id, entry.id, file.id)}
                                    className="text-slate-300 hover:text-rose-500 transition ml-2"
                                  >
                                    <i className="fas fa-times-circle text-xs"></i>
                                  </button>
                                </div>
                              ))}
                              {entry.files.length === 0 && <p className="text-xs text-slate-400 italic">Nessun file caricato per questo rendiconto.</p>}
                            </div>
                            <label className="inline-flex items-center space-x-2 cursor-pointer text-xs font-bold text-emerald-600 hover:text-emerald-700 transition">
                              <i className="fas fa-upload"></i>
                              <span>Aggiungi File</span>
                              <input
                                type="file"
                                accept=".pdf"
                                multiple
                                className="hidden"
                                onChange={(e) => e.target.files && addFilesToEntry(activeFolder.id, entry.id, e.target.files)}
                              />
                            </label>
                          </div>
                        </div>
                      </div>
                    ))}

                    {activeFolder.entries.length === 0 && (
                      <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center">
                        <p className="text-slate-400 text-sm">Nessun rendiconto ancora creato in questa cartella.</p>
                        <button onClick={() => createEntry(activeFolder.id)} className="mt-4 text-emerald-600 font-bold hover:underline">Crea il primo rendiconto</button>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {view === AppView.REPORT_VIEW && activeEntry?.report && (
                <div>
                  <div className="mb-6 flex items-center justify-between">
                    <button
                      onClick={() => setView(AppView.FOLDER_DETAIL)}
                      className="text-slate-500 hover:text-slate-900 transition flex items-center text-sm font-medium"
                    >
                      <i className="fas fa-chevron-left mr-2"></i> Torna a {activeFolder?.name}
                    </button>
                    <div className="flex space-x-2">
                       <button className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-600 hover:bg-slate-50 transition">
                        <i className="fas fa-download mr-1"></i> Esporta PDF
                      </button>
                      <button className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-600 hover:bg-slate-50 transition">
