import { jsPDF } from "jspdf";
import { AuditReport } from "../types";

export async function generatePdfReport(report: AuditReport, entryTitle: string, folderName: string) {
  const doc = new jsPDF();
  const margin = 20;
  let y = 20;

  // Header
  doc.setFillColor(15, 23, 42); // slate-900
  doc.rect(0, 0, 210, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("CondoAudit AI", margin, 20);

  doc.setFontSize(10);
  doc.setTextColor(16, 185, 129); // emerald-500
  doc.text("IL REVISORE DIGITALE ANACI-ORIENTED", margin, 28);

  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(`Report generato il: ${new Date().toLocaleDateString('it-IT')}`, 150, 28);

  y = 55;

  // Info Section
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text(`Condominio: ${folderName}`, margin, y);
  y += 8;
  doc.setFontSize(12);
  doc.setFont("helvetica", "normal");
  doc.text(`Oggetto: Audit Rendiconto - ${entryTitle}`, margin, y);
  y += 12;

  // Accounting Method Highlight
  doc.setFillColor(248, 250, 252); // slate-50
  doc.rect(margin, y, 170, 15, 'F');
  doc.setDrawColor(226, 232, 240); // slate-200
  doc.rect(margin, y, 170, 15, 'S');

  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.text("Metodo Contabile Rilevato:", margin + 5, y + 10);
  doc.setTextColor(16, 185, 129);
  doc.text(report.accountingMethodDetected.toUpperCase(), margin + 55, y + 10);

  y += 25;

  // Checklist
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Checklist di Controllo (Standard ANACI)", margin, y);
  y += 10;

  report.checklist.forEach(item => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    let statusText = "[ ] ";
    if (item.status === 'success') { statusText = "[V] "; doc.setTextColor(16, 185, 129); }
    else if (item.status === 'warning') { statusText = "[!] "; doc.setTextColor(245, 158, 11); }
    else if (item.status === 'error') { statusText = "[X] "; doc.setTextColor(225, 29, 72); }

    doc.text(`${statusText}${item.label}`, margin, y);
    y += 5;
    doc.setTextColor(100, 100, 100);
    doc.setFont("helvetica", "italic");
    const commentLines = doc.splitTextToSize(item.comment, 160);
    doc.text(commentLines, margin + 5, y);
    y += (commentLines.length * 4) + 4;
    doc.setTextColor(15, 23, 42);

    if (y > 270) { doc.addPage(); y = 20; }
  });

  y += 10;

  // Findings Sections
  const sections = [
    { title: "PUNTI DI FORZA", items: report.strengths, color: [16, 185, 129] },
    { title: "SUGGERIMENTI DI MIGLIORAMENTO", items: report.improvements, color: [245, 158, 11] },
    { title: "CORREZIONI NECESSARIE", items: report.corrections, color: [100, 116, 139] },
    { title: "CRITICITÀ (RISCHIO IMPUGNAZIONE)", items: report.criticalities, color: [225, 29, 72] }
  ];

  sections.forEach(sec => {
    if (y > 250) { doc.addPage(); y = 20; }

    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(sec.color[0], sec.color[1], sec.color[2]);
    doc.text(sec.title, margin, y);
    y += 7;

    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    doc.setFont("helvetica", "normal");

    if (sec.items.length === 0) {
      doc.text("- Nessun rilievo specifico identificato.", margin + 5, y);
      y += 6;
    } else {
      sec.items.forEach(item => {
        const lines = doc.splitTextToSize(`• ${item}`, 170);
        doc.text(lines, margin + 2, y);
        y += (lines.length * 5) + 2;
        if (y > 275) { doc.addPage(); y = 20; }
      });
    }
    y += 8;
  });

  // Simulator
  if (y > 240) { doc.addPage(); y = 20; }
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("Simulatore di Assemblea (Q&A)", margin, y);
  y += 10;

  report.assemblySimulator.forEach(qa => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text(`D: ${qa.question}`, margin, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    const respLines = doc.splitTextToSize(`R: ${qa.suggestedResponse}`, 170);
    doc.text(respLines, margin, y);
    y += (respLines.length * 5) + 3;

    if (qa.legalBasis) {
      doc.setFontSize(8);
      doc.setTextColor(16, 185, 129);
      doc.text(`Riferimento: ${qa.legalBasis}`, margin, y);
      y += 6;
      doc.setTextColor(15, 23, 42);
    }
    y += 5;
    if (y > 275) { doc.addPage(); y = 20; }
  });

  // Footer on each page
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.text(`CondoAudit AI - Report Tecnico Professionale - Pagina ${i} di ${pageCount}`, margin, 290);
  }

  doc.save(`Audit_${folderName.replace(/\s/g, '_')}_${entryTitle.replace(/\s/g, '_')}.pdf`);
}

import React, { useState } from 'react';
import { AuditReport } from '../types';
import { generatePdfReport } from '../services/pdfService';

interface AuditDashboardProps {
  report: AuditReport;
  onReset: () => void;
  entryTitle?: string;
  folderName?: string;
}

export const AuditDashboard: React.FC<AuditDashboardProps> = ({ report, onReset, entryTitle = "Rendiconto", folderName = "Condominio" }) => {
  const [isExporting, setIsExporting] = useState(false);

  const handleExportPdf = async () => {
    setIsExporting(true);
    try {
      await generatePdfReport(report, entryTitle, folderName);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Errore durante l'esportazione del PDF.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Overview Header */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="bg-slate-900 p-6 flex flex-col md:flex-row md:items-center justify-between text-white">
          <div>
            <h2 className="text-2xl font-bold">Rapporto di Revisione Digitale</h2>
            <p className="text-slate-400 text-sm mt-1">Metodo rilevato: <span className="text-emerald-400 font-mono uppercase font-bold">{report.accountingMethodDetected}</span></p>
          </div>
          <div className="flex space-x-2 mt-4 md:mt-0">
            <button 
              onClick={handleExportPdf}
              disabled={isExporting}
              className="text-xs px-4 py-2 bg-emerald-600 hover:bg-emerald-700 rounded-lg transition flex items-center disabled:opacity-50"
            >
              <i className={`fas ${isExporting ? 'fa-spinner fa-spin' : 'fa-file-pdf'} mr-2`}></i> 
              {isExporting ? 'Esportazione...' : 'Esporta PDF'}
            </button>
            <button 
              onClick={onReset}
              className="text-xs px-4 py-2 border border-slate-700 rounded-lg hover:bg-slate-800 transition"
            >
              Torna ai Rendiconti
            </button>
          </div>
        </div>

        <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6 border-b border-slate-100">
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.register ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Registro di Contabilità</span>
          </div>
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.summary ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Riepilogo Finanziario</span>
          </div>
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.note ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Nota Sintetica Esplicativa</span>
          </div>
        </div>
      </div>

      {/* Checklist Dashboard */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 col-span-full">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
            <i className="fas fa-tasks text-emerald-600 mr-2"></i> Checklist di Controllo ANACI
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
            {report.checklist.map((item) => (
              <div key={item.id} className="p-4 rounded-xl border border-slate-100 bg-slate-50 flex flex-col justify-between h-full">
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-bold uppercase text-slate-400 tracking-wider">Status</span>
                    {item.status === 'success' && <i className="fas fa-check-circle text-emerald-500"></i>}
                    {item.status === 'warning' && <i className="fas fa-exclamation-triangle text-amber-500"></i>}
                    {item.status === 'error' && <i className="fas fa-times-circle text-rose-500"></i>}
                  </div>
                  <p className="text-sm font-bold text-slate-700 leading-tight mb-2">{item.label}</p>
                </div>
                <p className="text-[11px] text-slate-500 italic mt-auto">{item.comment}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Audit Details */}
        <div className="lg:col-span-2 space-y-6">
          <Section cardTitle="Punti di Forza (Compliance)" icon="fa-award text-emerald-500" items={report.strengths} type="positive" />
          <Section cardTitle="Miglioramenti (Suggerimenti ANACI)" icon="fa-lightbulb text-amber-500" items={report.improvements} type="neutral" />
          <Section cardTitle="Correzioni Necessarie (Errori Tecnici)" icon="fa-wrench text-slate-500" items={report.corrections} type="warning" />
          <Section cardTitle="Criticità Gravi (Rischio Impugnazione)" icon="fa-gavel text-rose-600" items={report.criticalities} type="danger" />
        </div>

        {/* Assembly Simulator */}
        <div className="space-y-6">
          <div className="bg-slate-900 rounded-2xl p-6 text-white shadow-xl sticky top-24">
            <h3 className="text-lg font-bold mb-4 flex items-center">
              <i className="fas fa-comments-dollar text-emerald-400 mr-2"></i> Simulatore di Assemblea
            </h3>
            <p className="text-slate-400 text-xs mb-6">Domande probabili dei condomini basate sui punti critici rilevati.</p>

            <div className="space-y-6">
              {report.assemblySimulator.map((item, idx) => (
                <div key={idx} className="bg-slate-800 rounded-xl p-4 border-l-4 border-emerald-500">
                  <p className="text-xs font-bold text-emerald-300 mb-2 uppercase tracking-wide">Domanda Probabile:</p>
                  <p className="text-sm italic mb-3">"{item.question}"</p>
                  <div className="p-3 bg-slate-900 rounded-lg">
                    <p className="text-xs font-bold text-slate-400 mb-1 uppercase tracking-wide">Suggerimento Risposta:</p>
                    <p className="text-xs leading-relaxed">{item.suggestedResponse}</p>
                    {item.legalBasis && (
                      <p className="text-[10px] text-emerald-500/80 mt-2 font-mono">{item.legalBasis}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const Section: React.FC<{ cardTitle: string, icon: string, items: string[], type: 'positive' | 'neutral' | 'warning' | 'danger' }> = ({ cardTitle, icon, items, type }) => {
  const getColors = () => {
    switch(type) {
      case 'positive': return 'border-emerald-100 bg-emerald-50/30';
      case 'warning': return 'border-amber-100 bg-amber-50/30';
      case 'danger': return 'border-rose-100 bg-rose-50/30';
      default: return 'border-slate-100 bg-slate-50/30';
    }
  };

  return (
    <div className={`bg-white rounded-2xl shadow-sm border ${getColors()} p-6`}>
      <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
        <i className={`fas ${icon} mr-2`}></i> {cardTitle}
      </h3>
      <ul className="space-y-3">
        {items.length > 0 ? items.map((item, i) => (
          <li key={i} className="flex items-start space-x-3 text-sm text-slate-700">
            <span className="mt-1 w-1.5 h-1.5 rounded-full bg-slate-300 flex-shrink-0"></span>
            <span>{item}</span>
          </li>
        )) : (
          <li className="text-slate-400 text-xs italic">Nessun rilievo identificato in questa sezione.</li>
        )}
      </ul>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { AuditDashboard } from './components/AuditDashboard';
import { analyzeFinancialDocuments } from './services/geminiService';
import { AuditReport, AppState, Folder, StatementEntry, AppView, FileData } from './types';

const STORAGE_KEY = 'condoaudit_data';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [folders, setFolders] = useState<Folder[]>([]);
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeEntryId, setActiveEntryId] = useState<string | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [error, setError] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setFolders(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    } else {
      // Initial empty state
      setFolders([{ id: 'default', name: 'Condominio Esempio', entries: [] }]);
    }
  }, []);

  useEffect(() => {
    if (folders.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(folders));
    }
  }, [folders]);

  const activeFolder = folders.find(f => f.id === activeFolderId);
  const activeEntry = activeFolder?.entries.find(e => e.id === activeEntryId);

  const createFolder = () => {
    const name = prompt("Nome del nuovo condominio/cartella:");
    if (name) {
      const newFolder: Folder = { id: Date.now().toString(), name, entries: [] };
      setFolders([...folders, newFolder]);
    }
  };

  const createEntry = (folderId: string) => {
    const title = prompt("Titolo del rendiconto (es. Ordinario 2023):");
    if (title) {
      const newEntry: StatementEntry = {
        id: Date.now().toString(),
        title,
        files: [],
        status: 'draft',
        createdAt: Date.now()
      };
      setFolders(folders.map(f => f.id === folderId ? { ...f, entries: [newEntry, ...f.entries] } : f));
    }
  };

  const deleteFolder = (id: string) => {
    if (confirm("Eliminare definitivamente questa cartella e tutti i rendiconti contenuti?")) {
      setFolders(folders.filter(f => f.id !== id));
      if (activeFolderId === id) {
        setView(AppView.DASHBOARD);
        setActiveFolderId(null);
      }
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const base64String = reader.result as string;
        resolve(base64String.split(',')[1]);
      };
      reader.onerror = error => reject(error);
    });
  };

  const addFilesToEntry = async (folderId: string, entryId: string, files: FileList) => {
    const newFiles: FileData[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (file.type !== 'application/pdf') continue;
      const base64 = await fileToBase64(file);
      newFiles.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        base64,
        mimeType: file.type
      });
    }

    setFolders(folders.map(f => {
      if (f.id === folderId) {
        return {
          ...f,
          entries: f.entries.map(e => e.id === entryId ? { ...e, files: [...e.files, ...newFiles] } : e)
        };
      }
      return f;
    }));
  };

  const removeFileFromEntry = (folderId: string, entryId: string, fileId: string) => {
    setFolders(folders.map(f => {
      if (f.id === folderId) {
        return {
          ...f,
          entries: f.entries.map(e => e.id === entryId ? { ...e, files: e.files.filter(file => file.id !== fileId) } : e)
        };
      }
      return f;
    }));
  };

  const runAnalysis = async (folderId: string, entryId: string) => {
    const folder = folders.find(f => f.id === folderId);
    const entry = folder?.entries.find(e => e.id === entryId);
    if (!entry || entry.files.length === 0) return;

    setAppState(AppState.ANALYZING);
    setError(null);

    try {
      const report = await analyzeFinancialDocuments(entry.files);
      setFolders(folders.map(f => {
        if (f.id === folderId) {
          return {
            ...f,
            entries: f.entries.map(e => e.id === entryId ? { ...e, status: 'completed', report } : e)
          };
        }
        return f;
      }));
      setActiveEntryId(entryId);
      setView(AppView.REPORT_VIEW);
      setAppState(AppState.IDLE);
    } catch (err) {
      console.error(err);
      setError("Errore durante l'analisi. Riprova più tardi.");
      setAppState(AppState.IDLE);
    }
  };

  return (
    <Layout>
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar - Folders Navigation */}
        <aside className="w-full lg:w-64 flex-shrink-0 space-y-4">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400">Condomini</h3>
              <button onClick={createFolder} className="p-1 hover:text-emerald-600 transition">
                <i className="fas fa-plus-circle"></i>
              </button>
            </div>
            <nav className="space-y-1">
              {folders.map(folder => (
                <div key={folder.id} className="group flex items-center">
                  <button
                    onClick={() => {
                      setActiveFolderId(folder.id);
                      setView(AppView.FOLDER_DETAIL);
                    }}
                    className={`flex-grow text-left px-3 py-2 rounded-lg text-sm transition-all flex items-center space-x-2 ${activeFolderId === folder.id ? 'bg-emerald-50 text-emerald-700 font-semibold' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    <i className={`fas fa-folder${activeFolderId === folder.id ? '-open' : ''} ${activeFolderId === folder.id ? 'text-emerald-500' : 'text-slate-400'}`}></i>
                    <span className="truncate">{folder.name}</span>
                  </button>
                  <button onClick={() => deleteFolder(folder.id)} className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-rose-500 transition">
                    <i className="fas fa-trash-alt text-xs"></i>
                  </button>
                </div>
              ))}
              {folders.length === 0 && <p className="text-[11px] text-slate-400 italic p-3">Nessun condominio creato.</p>}
            </nav>
          </div>
        </aside>

        {/* Main Content Area */}
        <section className="flex-grow">
          {appState === AppState.ANALYZING ? (
            <div className="flex flex-col items-center justify-center py-24 space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <i className="fas fa-brain text-emerald-600 text-2xl animate-pulse"></i>
                </div>
              </div>
              <div className="text-center">
                <h3 className="text-xl font-bold text-slate-800">Analisi in corso...</h3>
                <p className="text-slate-500 text-sm mt-2">L'IA sta elaborando i file caricati per il rendiconto.</p>
              </div>
            </div>
          ) : (
            <>
              {view === AppView.DASHBOARD && (
                <div className="bg-white rounded-2xl p-12 text-center border border-slate-200 shadow-sm">
                  <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6">
                    <i className="fas fa-building text-3xl"></i>
                  </div>
                  <h2 className="text-2xl font-bold text-slate-800 mb-2">Benvenuto in CondoAudit AI</h2>
                  <p className="text-slate-500 max-w-md mx-auto mb-8">
                    Seleziona un condominio dalla barra laterale per gestire i rendiconti o creane uno nuovo per iniziare.
                  </p>
                  <button onClick={createFolder} className="px-6 py-3 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 transition">
                    Nuovo Condominio
                  </button>
                </div>
              )}

              {view === AppView.FOLDER_DETAIL && activeFolder && (
                <div className="space-y-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-2xl font-bold text-slate-900">{activeFolder.name}</h2>
                      <p className="text-slate-500 text-sm">Gestione rendiconti e audit</p>
                    </div>
                    <button
                      onClick={() => createEntry(activeFolder.id)}
                      className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm font-bold hover:bg-slate-800 transition flex items-center"
                    >
                      <i className="fas fa-plus mr-2"></i> Nuovo Rendiconto
                    </button>
                  </div>

                  <div className="grid grid-cols-1 gap-6">
                    {activeFolder.entries.map(entry => (
                      <div key={entry.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition hover:shadow-md">
                        <div className="p-6">
                          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div className="flex items-start space-x-4">
                              <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${entry.status === 'completed' ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>
                                <i className={`fas ${entry.status === 'completed' ? 'fa-file-circle-check' : 'fa-file-invoice'} text-xl`}></i>
                              </div>
                              <div>
                                <h3 className="text-lg font-bold text-slate-800">{entry.title}</h3>
                                <p className="text-xs text-slate-400">Creato il {new Date(entry.createdAt).toLocaleDateString('it-IT')}</p>
                                <div className="mt-2 flex space-x-2">
                                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${entry.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                                    {entry.status === 'completed' ? 'Analizzato' : 'Bozza'}
                                  </span>
                                  <span className="text-[10px] font-medium text-slate-400 flex items-center">
                                    <i className="fas fa-paperclip mr-1"></i> {entry.files.length} file
                                  </span>
                                </div>
                              </div>
                            </div>

                            <div className="flex items-center space-x-2">
                              {entry.status === 'completed' && (
                                <button
                                  onClick={() => {
                                    setActiveEntryId(entry.id);
                                    setView(AppView.REPORT_VIEW);
                                  }}
                                  className="px-4 py-2 bg-emerald-50 text-emerald-700 rounded-lg text-sm font-bold hover:bg-emerald-100 transition"
                                >
                                  Visualizza Report
                                </button>
                              )}
                              <button
                                onClick={() => runAnalysis(activeFolder.id, entry.id)}
                                disabled={entry.files.length === 0}
                                className={`px-4 py-2 rounded-lg text-sm font-bold transition flex items-center ${entry.files.length > 0 ? 'bg-slate-900 text-white hover:bg-slate-800' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}
                              >
                                {entry.status === 'completed' ? 'Riesegui Audit' : 'Avvia Audit'}
                              </button>
                            </div>
                          </div>

                          {/* Files Section */}
                          <div className="mt-6 pt-6 border-t border-slate-100">
                            <h4 className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3">Documenti caricati</h4>
                            <div className="flex flex-wrap gap-2 mb-4">
                              {entry.files.map(file => (
                                <div key={file.id} className="group relative bg-slate-50 border border-slate-200 px-3 py-1.5 rounded-lg flex items-center space-x-2">
                                  <i className="fas fa-file-pdf text-rose-500 text-xs"></i>
                                  <span className="text-xs text-slate-600 max-w-[150px] truncate">{file.name}</span>
                                  <button
                                    onClick={() => removeFileFromEntry(activeFolder.id, entry.id, file.id)}
                                    className="text-slate-300 hover:text-rose-500 transition ml-2"
                                  >
                                    <i className="fas fa-times-circle text-xs"></i>
                                  </button>
                                </div>
                              ))}
                              {entry.files.length === 0 && <p className="text-xs text-slate-400 italic">Nessun file caricato per questo rendiconto.</p>}
                            </div>
                            <label className="inline-flex items-center space-x-2 cursor-pointer text-xs font-bold text-emerald-600 hover:text-emerald-700 transition">
                              <i className="fas fa-upload"></i>
                              <span>Aggiungi File</span>
                              <input
                                type="file"
                                accept=".pdf"
                                multiple
                                className="hidden"
                                onChange={(e) => e.target.files && addFilesToEntry(activeFolder.id, entry.id, e.target.files)}
                              />
                            </label>
                          </div>
                        </div>
                      </div>
                    ))}

                    {activeFolder.entries.length === 0 && (
                      <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center">
                        <p className="text-slate-400 text-sm">Nessun rendiconto ancora creato in questa cartella.</p>
                        <button onClick={() => createEntry(activeFolder.id)} className="mt-4 text-emerald-600 font-bold hover:underline">Crea il primo rendiconto</button>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {view === AppView.REPORT_VIEW && activeEntry?.report && (
                <div>
                  <div className="mb-6 flex items-center justify-between">
                    <button
                      onClick={() => setView(AppView.FOLDER_DETAIL)}
                      className="text-slate-500 hover:text-slate-900 transition flex items-center text-sm font-medium"
                    >
                      <i className="fas fa-chevron-left mr-2"></i> Torna a {activeFolder?.name}
                    </button>
                  </div>
                  <AuditDashboard 
                    report={activeEntry.report} 
                    onReset={() => setView(AppView.FOLDER_DETAIL)} 
                    entryTitle={activeEntry.title}
                    folderName={activeFolder?.name}
                  />
                </div>
              )}
            </>
          )}

          {error && (
            <div className="mt-6 p-4 bg-rose-50 border border-rose-100 rounded-xl flex items-center space-x-3 text-rose-700">
              <i className="fas fa-exclamation-circle"></i>
              <p className="text-sm font-medium">{error}</p>
            </div>
          )}
        </section>
      </div>
    </Layout>
  );
};

export default App;

export interface AnalysisSection {
  title: string;
  items: string[];
}

export interface ChecklistItem {
  id: string;
  label: string;
  status: 'success' | 'warning' | 'error' | 'pending';
  comment: string;
}

export interface AssemblyQuestion {
  question: string;
  suggestedResponse: string;
  legalBasis: string;
}

export interface AuditReport {
  strengths: string[];
  improvements: string[];
  corrections: string[];
  criticalities: string[];
  checklist: ChecklistItem[];
  assemblySimulator: AssemblyQuestion[];
  accountingMethodDetected: 'Competenza' | 'Cassa' | 'Misto' | 'Non Rilevato';
  structuralVerification: {
    register: boolean;
    summary: boolean;
    note: boolean;
  };
}

export enum AppState {
  IDLE = 'idle',
  UPLOADING = 'uploading',
  ANALYZING = 'analyzing',
  REPORT_READY = 'report_ready',
  ERROR = 'error'
}

// Added AppView enum to define available views in the application
export enum AppView {
  DASHBOARD = 'dashboard',
  FOLDER_DETAIL = 'folder_detail',
  REPORT_VIEW = 'report_view'
}

// Added FileData interface for tracking uploaded document data
export interface FileData {
  id: string;
  name: string;
  base64: string;
  mimeType: string;
}

// Added StatementEntry interface to represent a single audit task
export interface StatementEntry {
  id: string;
  title: string;
  files: FileData[];
  status: 'draft' | 'completed';
  createdAt: number;
  report?: AuditReport;
}

// Added Folder interface for organizing audit tasks by building/condominium
export interface Folder {
  id: string;
  name: string;
  entries: StatementEntry[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport, FileData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_PROMPT = `
Sei un esperto revisore condominiale senior specializzato in legislazione italiana (Art. 1130 bis C.C.) e standard qualitativi ANACI.
Analizza il documento fornito (rendiconto condominiale) e produci un "Rapporto di Revisione" dettagliato.

Dovrai restituire un JSON strutturato con queste sezioni:
1. "strengths": Punti di forza (Compliance positiva).
2. "improvements": Suggerimenti di miglioramento basati sulla Guida ANACI.
3. "corrections": Errori tecnici o mancate quadrature.
4. "criticalities": Rischi di impugnazione (violazioni gravi).
5. "checklist": Valutazione semaforica di 5 punti chiave (Registro, Situazione Patrimoniale, Fondi, Rapporti in corso, Passaggio consegne).
6. "assemblySimulator": Simulatore di assemblea con domande probabili dei condomini e risposte suggerite.
7. "accountingMethodDetected": Rileva se è Competenza, Cassa o Misto.
8. "structuralVerification": Verifica presenza di Registro, Riepilogo, Nota.

Istruzioni di stile: professionale, tecnico ma intellegibile, citando capitoli della guida ANACI o articoli del Codice Civile dove pertinente.
`;

// Fixed: Renamed to plural and updated to handle array of FileData as expected by App.tsx
export async function analyzeFinancialDocuments(files: FileData[]): Promise<AuditReport> {
  const model = "gemini-3-pro-preview";

  const parts = [
    { text: ANALYSIS_PROMPT },
    ...files.map(file => ({
      inlineData: { data: file.base64, mimeType: file.mimeType }
    }))
  ];

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: parts
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          corrections: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalities: { type: Type.ARRAY, items: { type: Type.STRING } },
          checklist: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                label: { type: Type.STRING },
                status: { type: Type.STRING, description: "success, warning, error, pending" },
                comment: { type: Type.STRING }
              }
            }
          },
          assemblySimulator: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                suggestedResponse: { type: Type.STRING },
                legalBasis: { type: Type.STRING }
              }
            }
          },
          accountingMethodDetected: { type: Type.STRING },
          structuralVerification: {
            type: Type.OBJECT,
            properties: {
              register: { type: Type.BOOLEAN },
              summary: { type: Type.BOOLEAN },
              note: { type: Type.BOOLEAN }
            }
          }
        },
        required: ["strengths", "improvements", "corrections", "criticalities", "checklist", "assemblySimulator", "accountingMethodDetected", "structuralVerification"]
      }
    }
  });

  const text = response.text || "{}";
  return JSON.parse(text) as AuditReport;
}

import { jsPDF } from "jspdf";
import { AuditReport } from "../types";

export async function generatePdfReport(report: AuditReport) {
  const doc = new jsPDF();
  const margin = 20;
  let y = 20;

  // Header
  doc.setFillColor(15, 23, 42); // slate-900
  doc.rect(0, 0, 210, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("CondoAudit AI", margin, 20);

  doc.setFontSize(10);
  doc.setTextColor(16, 185, 129); // emerald-500
  doc.text("IL REVISORE DIGITALE ANACI-ORIENTED", margin, 28);

  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(`Generato il: ${new Date().toLocaleDateString('it-IT')}`, 160, 28);

  y = 55;

  // Title Section
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Rapporto di Revisione Condominiale", margin, y);
  y += 10;

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Metodo Contabile: ${report.accountingMethodDetected}`, margin, y);
  y += 15;

  // Checklist
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Checklist di Controllo", margin, y);
  y += 8;

  report.checklist.forEach(item => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    let status = "[ ] ";
    if (item.status === 'success') { status = "[V] "; doc.setTextColor(16, 185, 129); }
    else if (item.status === 'warning') { status = "[!] "; doc.setTextColor(245, 158, 11); }
    else if (item.status === 'error') { status = "[X] "; doc.setTextColor(225, 29, 72); }

    doc.text(`${status}${item.label}`, margin, y);
    y += 5;

    doc.setTextColor(80, 80, 80);
    doc.setFont("helvetica", "normal");
    const commentLines = doc.splitTextToSize(item.comment, 170);
    doc.text(commentLines, margin + 5, y);
    y += (commentLines.length * 5) + 5;

    doc.setTextColor(15, 23, 42);
    if (y > 270) { doc.addPage(); y = 20; }
  });

  y += 10;

  // Audit Details
  const sections = [
    { title: "PUNTI DI FORZA", items: report.strengths, color: [16, 185, 129] },
    { title: "SUGGERIMENTI DI MIGLIORAMENTO", items: report.improvements, color: [245, 158, 11] },
    { title: "CORREZIONI NECESSARIE", items: report.corrections, color: [100, 116, 139] },
    { title: "CRITICITÀ RILEVATE", items: report.criticalities, color: [225, 29, 72] }
  ];

  sections.forEach(sec => {
    if (y > 250) { doc.addPage(); y = 20; }

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(sec.color[0], sec.color[1], sec.color[2]);
    doc.text(sec.title, margin, y);
    y += 7;

    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    doc.setFont("helvetica", "normal");

    if (sec.items.length === 0) {
      doc.text("- Nessun rilievo specifico.", margin + 5, y);
      y += 6;
    } else {
      sec.items.forEach(item => {
        const lines = doc.splitTextToSize(`• ${item}`, 170);
        doc.text(lines, margin + 2, y);
        y += (lines.length * 5) + 2;
        if (y > 275) { doc.addPage(); y = 20; }
      });
    }
    y += 8;
  });

  // Simulator
  if (y > 240) { doc.addPage(); y = 20; }
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("SIMULATORE DI ASSEMBLEA (Q&A)", margin, y);
  y += 10;

  report.assemblySimulator.forEach(qa => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text(`D: ${qa.question}`, margin, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    const respLines = doc.splitTextToSize(`R: ${qa.suggestedResponse}`, 170);
    doc.text(respLines, margin, y);
    y += (respLines.length * 5) + 3;

    if (qa.legalBasis) {
      doc.setFontSize(8);
      doc.setTextColor(16, 185, 129);
      doc.text(`Riferimento Legale: ${qa.legalBasis}`, margin, y);
      y += 6;
    }
    y += 4;
    doc.setTextColor(15, 23, 42);
    if (y > 275) { doc.addPage(); y = 20; }
  });

  doc.save(`Rapporto_Revisione_${new Date().getTime()}.pdf`);
}

