import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_PROMPT = `
Sei un esperto revisore condominiale senior specializzato in legislazione italiana (Art. 1130 bis C.C.) e standard qualitativi ANACI.
Analizza il documento fornito (rendiconto condominiale) e produci un "Rapporto di Revisione" dettagliato.

Dovrai restituire un JSON strutturato con queste sezioni:
1. "strengths": Punti di forza (Compliance positiva).
2. "improvements": Suggerimenti di miglioramento basati sulla Guida ANACI.
3. "corrections": Errori tecnici o mancate quadrature.
4. "criticalities": Rischi di impugnazione (violazioni gravi).
5. "checklist": Valutazione semaforica di 5 punti chiave (Registro, Situazione Patrimoniale, Fondi, Rapporti in corso, Passaggio consegne).
6. "assemblySimulator": Simulatore di assemblea con domande probabili dei condomini e risposte suggerite.
7. "accountingMethodDetected": Rileva se è Competenza, Cassa o Misto.
8. "structuralVerification": Verifica presenza di Registro, Riepilogo, Nota.
9. "overallScore": Un punteggio da 1 a 100 che esprima la qualità e la compliance del rendiconto (100 è eccellente, <50 è critico).

Istruzioni di stile: professionale, tecnico ma intellegibile, citando capitoli della guida ANACI o articoli del Codice Civile dove pertinente.
`;

export async function analyzeFinancialDocument(fileBase64: string, mimeType: string): Promise<AuditReport> {
  const model = "gemini-3-pro-preview";

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { text: ANALYSIS_PROMPT },
        { inlineData: { data: fileBase64, mimeType } }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          corrections: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalities: { type: Type.ARRAY, items: { type: Type.STRING } },
          checklist: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                label: { type: Type.STRING },
                status: { type: Type.STRING, description: "success, warning, error, pending" },
                comment: { type: Type.STRING }
              }
            }
          },
          assemblySimulator: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                suggestedResponse: { type: Type.STRING },
                legalBasis: { type: Type.STRING }
              }
            }
          },
          accountingMethodDetected: { type: Type.STRING },
          structuralVerification: {
            type: Type.OBJECT,
            properties: {
              register: { type: Type.BOOLEAN },
              summary: { type: Type.BOOLEAN },
              note: { type: Type.BOOLEAN }
            }
          },
          overallScore: { type: Type.INTEGER, description: "Score from 1 to 100" }
        },
        required: ["strengths", "improvements", "corrections", "criticalities", "checklist", "assemblySimulator", "accountingMethodDetected", "structuralVerification", "overallScore"]
      }
    }
  });

  const text = response.text || "{}";
  return JSON.parse(text) as AuditReport;
}

