        )) : (
          <li className="text-slate-400 text-xs italic">Nessun rilievo identificato in questa sezione.</li>
        )}
      </ul>
    </div>
  );
};

import { jsPDF } from "jspdf";
import { AuditReport } from "../types";

export async function generatePdfReport(report: AuditReport) {
  const doc = new jsPDF();
  const margin = 20;
  let y = 20;

  // Header
  doc.setFillColor(15, 23, 42); // slate-900
  doc.rect(0, 0, 210, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("CondoAudit AI", margin, 20);

  doc.setFontSize(10);
  doc.setTextColor(16, 185, 129); // emerald-500
  doc.text("IL REVISORE DIGITALE ANACI-ORIENTED", margin, 28);

  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(`Generato il: ${new Date().toLocaleDateString('it-IT')}`, 160, 28);

  y = 55;

  // Score & Status Section (New)
  doc.setFillColor(248, 250, 252); // slate-50
  doc.rect(margin, y - 5, 170, 30, 'F');
  doc.setDrawColor(226, 232, 240); // slate-200
  doc.rect(margin, y - 5, 170, 30, 'S');

  doc.setTextColor(15, 23, 42);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Punteggio Globale Rendiconto:", margin + 5, y + 5);

  let scoreColor = [16, 185, 129]; // green
  let statusText = "PROFESSIONALE / ECCELLENTE";
  if (report.overallScore < 70) {
    scoreColor = [245, 158, 11]; // amber
    statusText = "NECESSITA MIGLIORAMENTI";
  }
  if (report.overallScore < 40) {
    scoreColor = [225, 29, 72]; // rose
    statusText = "CRITICO / NON CONFORME";
  }

  doc.setTextColor(scoreColor[0], scoreColor[1], scoreColor[2]);
  doc.setFontSize(24);
  doc.text(`${report.overallScore}/100`, margin + 120, y + 10);

  doc.setFontSize(10);
  doc.text(statusText, margin + 5, y + 15);

  y += 35;

  // Title Section
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Rapporto di Revisione Condominiale", margin, y);
  y += 10;

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Metodo Contabile: ${report.accountingMethodDetected}`, margin, y);
  y += 15;

  // Checklist
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Checklist di Controllo", margin, y);
  y += 8;

  report.checklist.forEach(item => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    let status = "[ ] ";
    if (item.status === 'success') { status = "[V] "; doc.setTextColor(16, 185, 129); }
    else if (item.status === 'warning') { status = "[!] "; doc.setTextColor(245, 158, 11); }
    else if (item.status === 'error') { status = "[X] "; doc.setTextColor(225, 29, 72); }

    doc.text(`${status}${item.label}`, margin, y);
    y += 5;

    doc.setTextColor(80, 80, 80);
    doc.setFont("helvetica", "normal");
    const commentLines = doc.splitTextToSize(item.comment, 170);
    doc.text(commentLines, margin + 5, y);
    y += (commentLines.length * 5) + 5;

    doc.setTextColor(15, 23, 42);
    if (y > 270) { doc.addPage(); y = 20; }
  });

  y += 10;

  // Audit Details
  const sections = [
    { title: "PUNTI DI FORZA", items: report.strengths, color: [16, 185, 129] },
    { title: "SUGGERIMENTI DI MIGLIORAMENTO", items: report.improvements, color: [245, 158, 11] },
    { title: "CORREZIONI NECESSARIE", items: report.corrections, color: [100, 116, 139] },
    { title: "CRITICITÀ RILEVATE", items: report.criticalities, color: [225, 29, 72] }
  ];

  sections.forEach(sec => {
    if (y > 250) { doc.addPage(); y = 20; }

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(sec.color[0], sec.color[1], sec.color[2]);
    doc.text(sec.title, margin, y);
    y += 7;

    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    doc.setFont("helvetica", "normal");

    if (sec.items.length === 0) {
      doc.text("- Nessun rilievo specifico.", margin + 5, y);
      y += 6;
    } else {
      sec.items.forEach(item => {
        const lines = doc.splitTextToSize(`• ${item}`, 170);
        doc.text(lines, margin + 2, y);
        y += (lines.length * 5) + 2;
        if (y > 275) { doc.addPage(); y = 20; }
      });
    }
    y += 8;
  });

  // Simulator
  if (y > 240) { doc.addPage(); y = 20; }
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("SIMULATORE DI ASSEMBLEA (Q&A)", margin, y);
  y += 10;

  report.assemblySimulator.forEach(qa => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text(`D: ${qa.question}`, margin, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    const respLines = doc.splitTextToSize(qa.suggestedResponse, 170);
    doc.text(`R: ${respLines}`, margin, y);
    y += (respLines.length * 5) + 3;

    if (qa.legalBasis) {
      doc.setFontSize(8);
      doc.setTextColor(16, 185, 129);
      doc.text(`Riferimento Legale: ${qa.legalBasis}`, margin, y);
      y += 6;
    }
    y += 4;
    doc.setTextColor(15, 23, 42);
    if (y > 275) { doc.addPage(); y = 20; }
  });

  doc.save(`Rapporto_Revisione_${new Date().getTime()}.pdf`);
}

