                    {item.status === 'warning' && <i className="fas fa-exclamation-triangle text-amber-500"></i>}
                    {item.status === 'error' && <i className="fas fa-times-circle text-rose-500"></i>}
                  </div>
                  <p className="text-sm font-bold text-slate-700 leading-tight mb-2">{item.label}</p>
                </div>
                <p className="text-[11px] text-slate-500 italic mt-auto">{item.comment}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Audit Details */}
        <div className="lg:col-span-2 space-y-6">
          <Section cardTitle="Punti di Forza (Compliance)" icon="fa-award text-emerald-500" items={report.strengths} type="positive" />
          <Section cardTitle="Miglioramenti (Suggerimenti ANACI)" icon="fa-lightbulb text-amber-500" items={report.improvements} type="neutral" />
          <Section cardTitle="Correzioni Necessarie (Errori Tecnici)" icon="fa-wrench text-slate-500" items={report.corrections} type="warning" />
          <Section cardTitle="Criticità Gravi (Rischio Impugnazione)" icon="fa-gavel text-rose-600" items={report.criticalities} type="danger" />
        </div>

        {/* Assembly Simulator */}
        <div className="space-y-6">
          <div className="bg-slate-900 rounded-2xl p-6 text-white shadow-xl sticky top-24">
            <h3 className="text-lg font-bold mb-4 flex items-center">
              <i className="fas fa-comments-dollar text-emerald-400 mr-2"></i> Simulatore di Assemblea
            </h3>
            <p className="text-slate-400 text-xs mb-6">Domande probabili dei condomini basate sui punti critici rilevati.</p>

            <div className="space-y-6">
              {report.assemblySimulator.map((item, idx) => (
                <div key={idx} className="bg-slate-800 rounded-xl p-4 border-l-4 border-emerald-500">
                  <p className="text-xs font-bold text-emerald-300 mb-2 uppercase tracking-wide">Domanda Probabile:</p>
                  <p className="text-sm italic mb-3">"{item.question}"</p>
                  <div className="p-3 bg-slate-900 rounded-lg">
                    <p className="text-xs font-bold text-slate-400 mb-1 uppercase tracking-wide">Suggerimento Risposta:</p>
                    <p className="text-xs leading-relaxed">{item.suggestedResponse}</p>
                    {item.legalBasis && (
                      <p className="text-[10px] text-emerald-500/80 mt-2 font-mono">{item.legalBasis}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const Section: React.FC<{ cardTitle: string, icon: string, items: string[], type: 'positive' | 'neutral' | 'warning' | 'danger' }> = ({ cardTitle, icon, items, type }) => {
  const getColors = () => {
    switch(type) {
      case 'positive': return 'border-emerald-100 bg-emerald-50/30';
      case 'warning': return 'border-amber-100 bg-amber-50/30';
      case 'danger': return 'border-rose-100 bg-rose-50/30';
      default: return 'border-slate-100 bg-slate-50/30';
    }
  };

  return (
    <div className={`bg-white rounded-2xl shadow-sm border ${getColors()} p-6`}>
      <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
        <i className={`fas ${icon} mr-2`}></i> {cardTitle}
      </h3>
      <ul className="space-y-3">
        {items.length > 0 ? items.map((item, i) => (
          <li key={i} className="flex items-start space-x-3 text-sm text-slate-700">
            <span className="mt-1 w-1.5 h-1.5 rounded-full bg-slate-300 flex-shrink-0"></span>
            <span>{item}</span>
          </li>
        )) : (
          <li className="text-slate-400 text-xs italic">Nessun rilievo identificato in questa sezione.</li>
        )}
      </ul>
    </div>
  );
};

import { jsPDF } from "jspdf";
import { AuditReport } from "../types";

export async function generatePdfReport(report: AuditReport) {
  const doc = new jsPDF();
  const margin = 20;
  const pageWidth = 210;
  const contentWidth = pageWidth - (margin * 2);
  let y = 20;

  // Helper for page breaks
  const checkPageBreak = (neededSpace: number) => {
    if (y + neededSpace > 280) {
      doc.addPage();
      y = 20;
      return true;
    }
    return false;
  };

  // Header
  doc.setFillColor(15, 23, 42); // slate-900
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("CondoAudit AI", margin, 20);

  doc.setFontSize(10);
  doc.setTextColor(16, 185, 129); // emerald-500
  doc.text("IL REVISORE DIGITALE ANACI-ORIENTED", margin, 28);

  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(`Generato il: ${new Date().toLocaleDateString('it-IT')}`, 160, 28);

  y = 55;

  // Condo Info & Score Section
  doc.setFillColor(248, 250, 252); // slate-50
  doc.rect(margin, y - 5, contentWidth, 35, 'F');
  doc.setDrawColor(226, 232, 240); // slate-200
  doc.rect(margin, y - 5, contentWidth, 35, 'S');

  doc.setTextColor(15, 23, 42);
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text(`Condominio: ${report.condoName}`, margin + 5, y + 5);
  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Periodo Gestione: ${report.managementPeriod}`, margin + 5, y + 12);
  doc.text(`Metodo Contabile: ${report.accountingMethodDetected}`, margin + 5, y + 19);

  let scoreColor: [number, number, number] = [16, 185, 129]; // green
  let statusText = "PROFESSIONALE / ECCELLENTE";
  if (report.overallScore < 70) {
    scoreColor = [245, 158, 11]; // amber
    statusText = "NECESSITA MIGLIORAMENTI";
  }
  if (report.overallScore < 40) {
    scoreColor = [225, 29, 72]; // rose
    statusText = "CRITICO / NON CONFORME";
  }

  doc.setTextColor(scoreColor[0], scoreColor[1], scoreColor[2]);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text(`${report.overallScore}/100`, margin + 130, y + 12);

  doc.setFontSize(9);
  doc.text(statusText, margin + 5, y + 26);

  y += 45;

  // Title Section
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Rapporto di Revisione Condominiale", margin, y);
  y += 12;

  // Checklist
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Checklist di Controllo (Art. 1130 bis C.C.)", margin, y);
  y += 10;

  report.checklist.forEach(item => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    let statusPrefix = "[ ] ";
    if (item.status === 'success') { statusPrefix = "[V] "; doc.setTextColor(16, 185, 129); }
    else if (item.status === 'warning') { statusPrefix = "[!] "; doc.setTextColor(245, 158, 11); }
    else if (item.status === 'error') { statusPrefix = "[X] "; doc.setTextColor(225, 29, 72); }

    const labelLines = doc.splitTextToSize(`${statusPrefix}${item.label}`, contentWidth);
    checkPageBreak(labelLines.length * 5 + 10);
    doc.text(labelLines, margin, y);
    y += (labelLines.length * 5);

    doc.setTextColor(80, 80, 80);
    doc.setFont("helvetica", "normal");
    const commentLines = doc.splitTextToSize(item.comment || "Nessun commento aggiuntivo.", contentWidth - 10);
    checkPageBreak(commentLines.length * 5 + 5);
    doc.text(commentLines, margin + 5, y);
    y += (commentLines.length * 5) + 8;

    doc.setTextColor(15, 23, 42);
  });

  y += 5;

  // Detailed Audit Sections
  const sections = [
    { title: "PUNTI DI FORZA (Compliance)", items: report.strengths, color: [16, 185, 129] as [number, number, number] },
    { title: "SUGGERIMENTI DI MIGLIORAMENTO (ANACI)", items: report.improvements, color: [245, 158, 11] as [number, number, number] },
    { title: "CORREZIONI NECESSARIE", items: report.corrections, color: [100, 116, 139] as [number, number, number] },
    { title: "CRITICITÀ RILEVATE (Rischio Impugnazione)", items: report.criticalities, color: [225, 29, 72] as [number, number, number] }
  ];

  sections.forEach(sec => {
    checkPageBreak(15);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(sec.color[0], sec.color[1], sec.color[2]);
    doc.text(sec.title, margin, y);
    y += 8;

    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    doc.setFont("helvetica", "normal");

    if (!sec.items || sec.items.length === 0) {
      doc.text("- Nessun rilievo specifico rilevato in questa sezione.", margin + 5, y);
      y += 8;
    } else {
      sec.items.forEach(item => {
        const lines = doc.splitTextToSize(`• ${item}`, contentWidth - 5);
        checkPageBreak(lines.length * 5 + 2);
        doc.text(lines, margin + 2, y);
        y += (lines.length * 5) + 3;
      });
      y += 5;
    }
  });

  // Simulator
  y += 5;
  checkPageBreak(20);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("SIMULATORE DI ASSEMBLEA (Q&A)", margin, y);
  y += 10;

  if (!report.assemblySimulator || report.assemblySimulator.length === 0) {
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text("Nessun quesito simulato disponibile.", margin, y);
    y += 10;
  } else {
    report.assemblySimulator.forEach(qa => {
      const qLines = doc.splitTextToSize(`D: ${qa.question}`, contentWidth);
      const rLines = doc.splitTextToSize(`R: ${qa.suggestedResponse}`, contentWidth);
      const spaceNeeded = (qLines.length * 5) + (rLines.length * 5) + (qa.legalBasis ? 10 : 10);

      checkPageBreak(spaceNeeded);

      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.text(qLines, margin, y);
      y += (qLines.length * 5) + 1;

      doc.setFont("helvetica", "normal");
      doc.text(rLines, margin, y);
      y += (rLines.length * 5) + 2;

      if (qa.legalBasis) {
        doc.setFontSize(8);
        doc.setTextColor(16, 185, 129);
        doc.setFont("helvetica", "italic");
        doc.text(`Riferimento Legale: ${qa.legalBasis}`, margin, y);
        y += 6;
      }
      y += 5;
      doc.setTextColor(15, 23, 42);
    });
  }

  // Footer on each page
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setTextColor(150, 150, 150);
    doc.text(`CondoAudit AI - ${report.condoName} - Pagina ${i} di ${pageCount}`, pageWidth / 2, 290, { align: 'center' });
  }

  doc.save(`Rapporto_Revisione_${report.condoName.replace(/\s+/g, '_')}_${new Date().getTime()}.pdf`);
}

