import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport, FileData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_PROMPT = `
Sei un esperto revisore condominiale senior specializzato in legislazione italiana (Art. 1130 bis C.C.) e standard qualitativi ANACI.
Ti vengono forniti uno o più documenti che compongono il fascicolo del rendiconto condominiale (es. Registro contabilità, Riepilogo finanziario, Nota esplicativa, Riparto).
Analizza i documenti forniti e produci un "Rapporto di Revisione" dettagliato e unitario.

Dovrai identificare obbligatoriamente:
- "condoName": Il nome del Condominio (cerca nell'intestazione dei documenti). Se non trovato, scrivi "Non identificato".
- "managementPeriod": Il periodo della gestione/esercizio (es. "01/01/2023 - 31/12/2023"). Se non trovato, scrivi "Non identificato".

Dovrai restituire un JSON strutturato con queste sezioni:
1. "condoName": Nome del condominio estratto.
2. "managementPeriod": Periodo di gestione estratto.
3. "strengths": Punti di forza (Compliance positiva).
4. "improvements": Suggerimenti di miglioramento basati sulla Guida ANACI.
5. "corrections": Errori tecnici o mancate quadrature.
6. "criticalities": Rischi di impugnazione (violazioni gravi).
7. "checklist": Valutazione semaforica di 5 punti chiave (Registro, Situazione Patrimoniale, Fondi, Rapporti in corso, Passaggio consegne). 
   Per ogni punto assegna un "score" parziale (da 0 a 20) in base alla qualità riscontrata.
8. "assemblySimulator": Simulatore di assemblea con domande probabili dei condomini e risposte suggerite.
9. "accountingMethodDetected": Rileva se è Competenza, Cassa o Misto.
10. "structuralVerification": Verifica presenza di Registro, Riepilogo, Nota.
11. "overallScore": Un punteggio da 1 a 100 che esprima la qualità e la compliance del rendiconto. Deve corrispondere alla somma degli "score" dei 5 punti della checklist.

Istruzioni di stile: professionale, tecnico ma intellegibile, citando capitoli della guida ANACI o articoli del Codice Civile dove pertinente.
`;

export async function analyzeFinancialDocuments(files: FileData[]): Promise<AuditReport> {
  const model = "gemini-3-pro-preview";

  const contentParts = [
    { text: ANALYSIS_PROMPT },
    ...files.map(f => ({
      inlineData: { data: f.base64, mimeType: f.mimeType }
    }))
  ];

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: contentParts
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          condoName: { type: Type.STRING },
          managementPeriod: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
          corrections: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalities: { type: Type.ARRAY, items: { type: Type.STRING } },
          checklist: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                label: { type: Type.STRING },
                status: { type: Type.STRING, description: "success, warning, error, pending" },
                comment: { type: Type.STRING },
                score: { type: Type.INTEGER, description: "Score from 0 to 20" }
              },
              required: ["id", "label", "status", "comment", "score"]
            }
          },
          assemblySimulator: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                suggestedResponse: { type: Type.STRING },
                legalBasis: { type: Type.STRING }
              }
            }
          },
          accountingMethodDetected: { type: Type.STRING },
          structuralVerification: {
            type: Type.OBJECT,
            properties: {
              register: { type: Type.BOOLEAN },
              summary: { type: Type.BOOLEAN },
              note: { type: Type.BOOLEAN }
            }
          },
          overallScore: { type: Type.INTEGER, description: "Score from 1 to 100" }
        },
        required: ["condoName", "managementPeriod", "strengths", "improvements", "corrections", "criticalities", "checklist", "assemblySimulator", "accountingMethodDetected", "structuralVerification", "overallScore"]
      }
    }
  });

  const text = response.text || "{}";
  return JSON.parse(text) as AuditReport;
}

import React, { useState } from 'react';
import { AuditReport } from '../types';
import { generatePdfReport } from '../services/pdfService';

interface AuditDashboardProps {
  report: AuditReport;
  onReset: () => void;
}

export const AuditDashboard: React.FC<AuditDashboardProps> = ({ report, onReset }) => {
  const [isExporting, setIsExporting] = useState(false);

  const handleExport = async () => {
    setIsExporting(true);
    try {
      await generatePdfReport(report);
    } catch (error) {
      console.error("Errore durante l'esportazione PDF:", error);
      alert("Si è verificato un errore durante la creazione del PDF.");
    } finally {
      setIsExporting(false);
    }
  };

  const getTrafficLightColor = (score: number) => {
    if (score >= 70) return 'text-emerald-500';
    if (score >= 40) return 'text-amber-500';
    return 'text-rose-500';
  };

  const getTrafficLightIcon = (score: number) => {
    if (score >= 70) return 'fa-circle-check';
    if (score >= 40) return 'fa-triangle-exclamation';
    return 'fa-circle-xmark';
  };

  const getScoreStatusLabel = (score: number) => {
    if (score >= 70) return 'Professionale / Eccellente';
    if (score >= 40) return 'Necessita Miglioramenti';
    return 'Critico / Non Conforme';
  };

  const getItemScoreColor = (score: number) => {
    if (score >= 15) return 'text-emerald-600';
    if (score >= 10) return 'text-amber-600';
    return 'text-rose-600';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Overview Header */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="bg-slate-900 p-6 flex flex-col md:flex-row md:items-center justify-between text-white">
          <div className="space-y-1">
            <h2 className="text-2xl font-bold">Rapporto di Revisione Digitale</h2>
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-slate-300 text-sm">
              <span className="flex items-center"><i className="fas fa-building mr-2 text-emerald-400"></i> {report.condoName}</span>
              <span className="flex items-center"><i className="fas fa-calendar-alt mr-2 text-emerald-400"></i> {report.managementPeriod}</span>
            </div>
            <p className="text-slate-400 text-[10px] mt-2">Metodo rilevato: <span className="text-emerald-400 font-mono uppercase font-bold">{report.accountingMethodDetected}</span></p>
          </div>
          <div className="flex space-x-3 mt-4 md:mt-0">
            <button 
              onClick={handleExport}
              disabled={isExporting}
              className="text-xs px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition flex items-center disabled:opacity-50"
            >
              <i className={`fas ${isExporting ? 'fa-spinner fa-spin' : 'fa-file-pdf'} mr-2`}></i>
              {isExporting ? 'Esportazione...' : 'Esporta PDF'}
            </button>
            <button 
              onClick={onReset}
              className="text-xs px-4 py-2 border border-slate-700 rounded-lg hover:bg-slate-800 transition"
            >
              Nuova Analisi
            </button>
          </div>
        </div>

        <div className="p-6 grid grid-cols-1 md:grid-cols-4 gap-6 border-b border-slate-100">
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.register ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Registro di Contabilità</span>
          </div>
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.summary ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Riepilogo Finanziario</span>
          </div>
          <div className="flex items-center space-x-4">
            <div className={`w-3 h-3 rounded-full ${report.structuralVerification.note ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
            <span className="text-sm font-medium">Nota Sintetica Esplicativa</span>
          </div>
          <div className="flex items-center space-x-4 border-l pl-6 border-slate-100">
            <div className="flex flex-col">
              <span className="text-[10px] uppercase font-bold text-slate-400">Punteggio Globale</span>
              <div className="flex items-center space-x-2">
                <span className={`text-xl font-black ${getTrafficLightColor(report.overallScore)}`}>{report.overallScore}/100</span>
                <i className={`fas ${getTrafficLightIcon(report.overallScore)} ${getTrafficLightColor(report.overallScore)}`}></i>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Traffic Light Visual Indicator */}
      <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 text-center">
        <h3 className="text-lg font-bold text-slate-800 mb-6 uppercase tracking-wider">Giudizio Generale del Rendiconto</h3>
        <div className="flex justify-center items-center space-x-8">
           <div className="flex flex-col items-center">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-2 ${report.overallScore < 40 ? 'bg-rose-500 shadow-[0_0_20px_rgba(225,29,72,0.5)]' : 'bg-rose-100 opacity-20'}`}>
                <i className="fas fa-traffic-light text-white text-2xl"></i>
              </div>
              <span className={`text-[10px] font-bold ${report.overallScore < 40 ? 'text-rose-600' : 'text-slate-300'}`}>ROSSO</span>
           </div>
           <div className="flex flex-col items-center">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-2 ${report.overallScore >= 40 && report.overallScore < 70 ? 'bg-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.5)]' : 'bg-amber-100 opacity-20'}`}>
                <i className="fas fa-traffic-light text-white text-2xl"></i>
              </div>
              <span className={`text-[10px] font-bold ${report.overallScore >= 40 && report.overallScore < 70 ? 'text-amber-600' : 'text-slate-300'}`}>GIALLO</span>
           </div>
           <div className="flex flex-col items-center">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-2 ${report.overallScore >= 70 ? 'bg-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.5)]' : 'bg-emerald-100 opacity-20'}`}>
                <i className="fas fa-traffic-light text-white text-2xl"></i>
              </div>
              <span className={`text-[10px] font-bold ${report.overallScore >= 70 ? 'text-emerald-600' : 'text-slate-300'}`}>VERDE</span>
           </div>
        </div>
        <div className="mt-8">
          <p className={`text-xl font-extrabold uppercase tracking-tight ${getTrafficLightColor(report.overallScore)}`}>
            {getScoreStatusLabel(report.overallScore)}
          </p>
          <p className="text-slate-500 text-sm mt-1 italic">Analisi basata sui criteri di trasparenza Art. 1130 bis C.C. e standard ANACI</p>
        </div>
      </div>

      {/* Checklist Dashboard */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 col-span-full">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
            <i className="fas fa-tasks text-emerald-600 mr-2"></i> Checklist di Controllo ANACI
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
            {report.checklist.map((item) => (
              <div key={item.id} className="p-4 rounded-xl border border-slate-100 bg-slate-50 flex flex-col justify-between h-full group hover:bg-white hover:shadow-md transition-all">
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <span className={`text-[11px] font-black ${getItemScoreColor(item.score)}`}>{item.score}/20</span>
                    {item.status === 'success' && <i className="fas fa-check-circle text-emerald-500"></i>}
                    {item.status === 'warning' && <i className="fas fa-exclamation-triangle text-amber-500"></i>}
                    {item.status === 'error' && <i className="fas fa-times-circle text-rose-500"></i>}
                  </div>
                  <p className="text-sm font-bold text-slate-700 leading-tight mb-2">{item.label}</p>
                </div>
                <p className="text-[11px] text-slate-500 italic mt-auto group-hover:text-slate-700 transition-colors">{item.comment}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Audit Details */}
        <div className="lg:col-span-2 space-y-6">
          <Section cardTitle="Punti di Forza (Compliance)" icon="fa-award text-emerald-500" items={report.strengths} type="positive" />
          <Section cardTitle="Miglioramenti (Suggerimenti ANACI)" icon="fa-lightbulb text-amber-500" items={report.improvements} type="neutral" />
          <Section cardTitle="Correzioni Necessarie (Errori Tecnici)" icon="fa-wrench text-slate-500" items={report.corrections} type="warning" />
          <Section cardTitle="Criticità Gravi (Rischio Impugnazione)" icon="fa-gavel text-rose-600" items={report.criticalities} type="danger" />
        </div>

        {/* Assembly Simulator */}
        <div className="space-y-6">
          <div className="bg-slate-900 rounded-2xl p-6 text-white shadow-xl sticky top-24">
            <h3 className="text-lg font-bold mb-4 flex items-center">
              <i className="fas fa-comments-dollar text-emerald-400 mr-2"></i> Simulatore di Assemblea
            </h3>
            <p className="text-slate-400 text-xs mb-6">Domande probabili dei condomini basate sui punti critici rilevati.</p>

            <div className="space-y-6">
              {report.assemblySimulator.map((item, idx) => (
                <div key={idx} className="bg-slate-800 rounded-xl p-4 border-l-4 border-emerald-500">
                  <p className="text-xs font-bold text-emerald-300 mb-2 uppercase tracking-wide">Domanda Probabile:</p>
                  <p className="text-sm italic mb-3">"{item.question}"</p>
                  <div className="p-3 bg-slate-900 rounded-lg">
                    <p className="text-xs font-bold text-slate-400 mb-1 uppercase tracking-wide">Suggerimento Risposta:</p>
                    <p className="text-xs leading-relaxed">{item.suggestedResponse}</p>
                    {item.legalBasis && (
                      <p className="text-[10px] text-emerald-500/80 mt-2 font-mono">{item.legalBasis}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const Section: React.FC<{ cardTitle: string, icon: string, items: string[], type: 'positive' | 'neutral' | 'warning' | 'danger' }> = ({ cardTitle, icon, items, type }) => {
  const getColors = () => {
    switch(type) {
      case 'positive': return 'border-emerald-100 bg-emerald-50/30';
      case 'warning': return 'border-amber-100 bg-amber-50/30';
      case 'danger': return 'border-rose-100 bg-rose-50/30';
      default: return 'border-slate-100 bg-slate-50/30';
    }
  };

  return (
    <div className={`bg-white rounded-2xl shadow-sm border ${getColors()} p-6`}>
      <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
        <i className={`fas ${icon} mr-2`}></i> {cardTitle}
      </h3>
      <ul className="space-y-3">
        {items.length > 0 ? items.map((item, i) => (
          <li key={i} className="flex items-start space-x-3 text-sm text-slate-700">
            <span className="mt-1 w-1.5 h-1.5 rounded-full bg-slate-300 flex-shrink-0"></span>
            <span>{item}</span>
          </li>
        )) : (
          <li className="text-slate-400 text-xs italic">Nessun rilievo identificato in questa sezione.</li>
        )}
      </ul>
    </div>
  );
};

import { jsPDF } from "jspdf";
import { AuditReport } from "../types";

export async function generatePdfReport(report: AuditReport) {
  const doc = new jsPDF();
  const margin = 20;
  const pageWidth = 210;
  const contentWidth = pageWidth - (margin * 2);
  let y = 20;

  // Helper for page breaks
  const checkPageBreak = (neededSpace: number) => {
    if (y + neededSpace > 280) {
      doc.addPage();
      y = 20;
      return true;
    }
    return false;
  };

  // Header
  doc.setFillColor(15, 23, 42); // slate-900
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("CondoAudit AI", margin, 20);

  doc.setFontSize(10);
  doc.setTextColor(16, 185, 129); // emerald-500
  doc.text("IL REVISORE DIGITALE ANACI-ORIENTED", margin, 28);

  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(`Generato il: ${new Date().toLocaleDateString('it-IT')}`, 160, 28);

  y = 55;

  // Condo Info & Score Section
  doc.setFillColor(248, 250, 252); // slate-50
  doc.rect(margin, y - 5, contentWidth, 35, 'F');
  doc.setDrawColor(226, 232, 240); // slate-200
  doc.rect(margin, y - 5, contentWidth, 35, 'S');

  doc.setTextColor(15, 23, 42);
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text(`Condominio: ${report.condoName}`, margin + 5, y + 5);
  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Periodo Gestione: ${report.managementPeriod}`, margin + 5, y + 12);
  doc.text(`Metodo Contabile: ${report.accountingMethodDetected}`, margin + 5, y + 19);

  let scoreColor: [number, number, number] = [16, 185, 129]; // green
  let statusText = "PROFESSIONALE / ECCELLENTE";
  if (report.overallScore < 70) {
    scoreColor = [245, 158, 11]; // amber
    statusText = "NECESSITA MIGLIORAMENTI";
  }
  if (report.overallScore < 40) {
    scoreColor = [225, 29, 72]; // rose
    statusText = "CRITICO / NON CONFORME";
  }

  doc.setTextColor(scoreColor[0], scoreColor[1], scoreColor[2]);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text(`${report.overallScore}/100`, margin + 130, y + 12);

  doc.setFontSize(9);
  doc.text(statusText, margin + 5, y + 26);

  y += 45;

  // Title Section
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Rapporto di Revisione Condominiale", margin, y);
  y += 12;

  // Checklist
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Checklist di Controllo (Dettaglio Punteggi)", margin, y);
  y += 10;

  report.checklist.forEach(item => {
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    let statusPrefix = "[ ] ";
    if (item.status === 'success') { statusPrefix = "[V] "; doc.setTextColor(16, 185, 129); }
    else if (item.status === 'warning') { statusPrefix = "[!] "; doc.setTextColor(245, 158, 11); }
    else if (item.status === 'error') { statusPrefix = "[X] "; doc.setTextColor(225, 29, 72); }

    // Header line: Status + Label + Score
    const scoreText = `(Punti: ${item.score}/20)`;
    const labelLines = doc.splitTextToSize(`${statusPrefix}${item.label} ${scoreText}`, contentWidth);
    checkPageBreak(labelLines.length * 5 + 10);
    doc.text(labelLines, margin, y);
    y += (labelLines.length * 5);

    doc.setTextColor(80, 80, 80);
    doc.setFont("helvetica", "normal");
    const commentLines = doc.splitTextToSize(item.comment || "Nessun commento aggiuntivo.", contentWidth - 10);
    checkPageBreak(commentLines.length * 5 + 5);
    doc.text(commentLines, margin + 5, y);
    y += (commentLines.length * 5) + 8;

    doc.setTextColor(15, 23, 42);
  });

  y += 5;

  // Detailed Audit Sections
  const sections = [
    { title: "PUNTI DI FORZA (Compliance)", items: report.strengths, color: [16, 185, 129] as [number, number, number] },
    { title: "SUGGERIMENTI DI MIGLIORAMENTO (ANACI)", items: report.improvements, color: [245, 158, 11] as [number, number, number] },
    { title: "CORREZIONI NECESSARIE", items: report.corrections, color: [100, 116, 139] as [number, number, number] },
    { title: "CRITICITÀ RILEVATE (Rischio Impugnazione)", items: report.criticalities, color: [225, 29, 72] as [number, number, number] }
  ];

  sections.forEach(sec => {
    checkPageBreak(15);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(sec.color[0], sec.color[1], sec.color[2]);
    doc.text(sec.title, margin, y);
    y += 8;

    doc.setFontSize(9);
    doc.setTextColor(60, 60, 60);
    doc.setFont("helvetica", "normal");

    if (!sec.items || sec.items.length === 0) {
      doc.text("- Nessun rilievo specifico rilevato in questa sezione.", margin + 5, y);
      y += 8;
    } else {
      sec.items.forEach(item => {
        const lines = doc.splitTextToSize(`• ${item}`, contentWidth - 5);
        checkPageBreak(lines.length * 5 + 2);
        doc.text(lines, margin + 2, y);
        y += (lines.length * 5) + 3;
      });
      y += 5;
    }
  });

  // Simulator
  y += 5;
  checkPageBreak(20);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("SIMULATORE DI ASSEMBLEA (Q&A)", margin, y);
  y += 10;

  if (!report.assemblySimulator || report.assemblySimulator.length === 0) {
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text("Nessun quesito simulato disponibile.", margin, y);
    y += 10;
  } else {
    report.assemblySimulator.forEach(qa => {
      const qLines = doc.splitTextToSize(`D: ${qa.question}`, contentWidth);
      const rLines = doc.splitTextToSize(`R: ${qa.suggestedResponse}`, contentWidth);
      const spaceNeeded = (qLines.length * 5) + (rLines.length * 5) + (qa.legalBasis ? 10 : 10);

      checkPageBreak(spaceNeeded);

      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.text(qLines, margin, y);
      y += (qLines.length * 5) + 1;

      doc.setFont("helvetica", "normal");
      doc.text(rLines, margin, y);
      y += (rLines.length * 5) + 2;

      if (qa.legalBasis) {
        doc.setFontSize(8);
        doc.setTextColor(16, 185, 129);
        doc.setFont("helvetica", "italic");
        doc.text(`Riferimento Legale: ${qa.legalBasis}`, margin, y);
        y += 6;
      }
      y += 5;
      doc.setTextColor(15, 23, 42);
    });
  }

  // Footer on each page
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setTextColor(150, 150, 150);
    doc.text(`CondoAudit AI - ${report.condoName} - Pagina ${i} di ${pageCount}`, pageWidth / 2, 290, { align: 'center' });
  }

  doc.save(`Rapporto_Revisione_${report.condoName.replace(/\s+/g, '_')}_${new Date().getTime()}.pdf`);
}
